performance_config = """// The New Civilization - Performance Optimization Configuration
// CDN, caching, and performance strategies

export const PerformanceConfig = {
  // CDN Configuration
  cdn: {
    enabled: true,
    regions: ['iad1', 'sfo1', 'lhr1', 'sin1', 'syd1'],
    staticAssets: {
      maxAge: '1y',
      staleWhileRevalidate: '1w',
      paths: ['/images/*', '/fonts/*', '/icons/*', '/_next/static/*']
    },
    apiRoutes: {
      maxAge: '1m',
      staleWhileRevalidate: '5m',
      paths: ['/api/hf/*', '/api/revenue/*']
    }
  },

  // Caching Strategy
  cache: {
    // Static Assets
    staticFiles: {
      'Cache-Control': 'public, max-age=31536000, immutable',
      'Expires': new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toUTCString()
    },

    // API Responses
    api: {
      default: 'public, s-maxage=60, stale-while-revalidate=300',
      realtime: 'public, s-maxage=10, stale-while-revalidate=60',
      revenue: 'private, s-maxage=30, stale-while-revalidate=120'
    },

    // HTML Pages
    pages: {
      static: 'public, s-maxage=3600, stale-while-revalidate=86400',
      dynamic: 'public, s-maxage=60, stale-while-revalidate=300'
    }
  },

  // Performance Budgets
  budgets: {
    javascript: '250kb',
    css: '50kb',
    fonts: '100kb',
    images: '500kb',
    total: '1mb'
  },

  // Optimization Features
  optimization: {
    // Image optimization
    images: {
      formats: ['webp', 'avif'],
      quality: 85,
      sizes: [640, 750, 828, 1080, 1200, 1920],
      domains: ['your-space.hf.space', 'cdn.thenewcivilization.com']
    },

    // Code splitting
    codeSplitting: {
      chunks: 'all',
      maxSize: 244000,
      minSize: 20000
    },

    // Compression
    compression: {
      gzip: true,
      brotli: true,
      threshold: 1024
    },

    // Preloading
    preload: {
      fonts: ['/fonts/inter.woff2', '/fonts/mono.woff2'],
      critical: ['/api/health', '/api/revenue/status']
    }
  }
};

// Edge Function for Performance Optimization
export function performanceMiddleware(request) {
  const { pathname } = new URL(request.url);

  // Apply caching headers based on path
  const headers = new Headers();

  if (pathname.startsWith('/_next/static/') || pathname.startsWith('/images/')) {
    headers.set('Cache-Control', PerformanceConfig.cache.staticFiles['Cache-Control']);
    headers.set('Expires', PerformanceConfig.cache.staticFiles['Expires']);
  } else if (pathname.startsWith('/api/')) {
    if (pathname.includes('revenue')) {
      headers.set('Cache-Control', PerformanceConfig.cache.api.revenue);
    } else if (pathname.includes('realtime')) {
      headers.set('Cache-Control', PerformanceConfig.cache.api.realtime);
    } else {
      headers.set('Cache-Control', PerformanceConfig.cache.api.default);
    }
  } else {
    // Regular pages
    headers.set('Cache-Control', PerformanceConfig.cache.pages.dynamic);
  }

  // Security headers
  headers.set('X-Content-Type-Options', 'nosniff');
  headers.set('X-Frame-Options', 'DENY');
  headers.set('X-XSS-Protection', '1; mode=block');

  return headers;
}

export default PerformanceConfig;
"""

