performance_monitor = """// Performance Monitoring Utilities
// Real-time performance tracking and optimization

export class PerformanceMonitor {
  constructor() {
    this.metrics = {
      pageLoad: {},
      apiRequests: {},
      revenue: {},
      errors: []
    };
    this.init();
  }

  init() {
    if (typeof window !== 'undefined') {
      this.trackPageLoad();
      this.trackApiRequests();
      this.trackUserInteractions();
    }
  }

  // Track page load performance
  trackPageLoad() {
    window.addEventListener('load', () => {
      const navigation = performance.getEntriesByType('navigation')[0];

      this.metrics.pageLoad = {
        domContentLoaded: navigation.domContentLoadedEventEnd - navigation.domContentLoadedEventStart,
        loadComplete: navigation.loadEventEnd - navigation.loadEventStart,
        totalLoadTime: navigation.loadEventEnd - navigation.fetchStart,
        firstContentfulPaint: this.getFCP(),
        largestContentfulPaint: this.getLCP(),
        cumulativeLayoutShift: this.getCLS(),
        firstInputDelay: this.getFID()
      };

      this.sendMetrics('page_load', this.metrics.pageLoad);
    });
  }

  // Track API request performance
  trackApiRequests() {
    const originalFetch = window.fetch;

    window.fetch = async (...args) => {
      const startTime = performance.now();
      const url = args[0];

      try {
        const response = await originalFetch(...args);
        const endTime = performance.now();
        const duration = endTime - startTime;

        // Track API performance
        this.metrics.apiRequests[url] = {
          duration,
          status: response.status,
          timestamp: new Date().toISOString()
        };

        // Track revenue API specifically
        if (url.includes('/api/revenue/')) {
          this.metrics.revenue.lastRequest = duration;
          this.metrics.revenue.averageResponseTime = this.calculateAverage(
            Object.values(this.metrics.apiRequests)
              .filter(req => req.url?.includes('/api/revenue/'))
              .map(req => req.duration)
          );
        }

        return response;
      } catch (error) {
        const endTime = performance.now();
        const duration = endTime - startTime;

        this.metrics.errors.push({
          type: 'api_error',
          url,
          duration,
          error: error.message,
          timestamp: new Date().toISOString()
        });

        throw error;
      }
    };
  }

  // Track user interactions for revenue optimization
  trackUserInteractions() {
    const revenueElements = document.querySelectorAll('[data-revenue-track]');

    revenueElements.forEach(element => {
      element.addEventListener('click', (event) => {
        const action = element.dataset.revenueTrack;

        this.sendMetrics('revenue_interaction', {
          action,
          timestamp: new Date().toISOString(),
          element: element.tagName.toLowerCase(),
          text: element.textContent?.substring(0, 50)
        });
      });
    });
  }

  // Core Web Vitals
  getFCP() {
    const entries = performance.getEntriesByName('first-contentful-paint');
    return entries.length > 0 ? entries[0].startTime : null;
  }

  getLCP() {
    return new Promise((resolve) => {
      new PerformanceObserver((entryList) => {
        const entries = entryList.getEntries();
        const lastEntry = entries[entries.length - 1];
        resolve(lastEntry.startTime);
      }).observe({ entryTypes: ['largest-contentful-paint'] });
    });
  }

  getCLS() {
    let clsValue = 0;

    new PerformanceObserver((entryList) => {
      for (const entry of entryList.getEntries()) {
        if (!entry.hadRecentInput) {
          clsValue += entry.value;
        }
      }
    }).observe({ entryTypes: ['layout-shift'] });

    return clsValue;
  }

  getFID() {
    return new Promise((resolve) => {
      new PerformanceObserver((entryList) => {
        const firstEntry = entryList.getEntries()[0];
        resolve(firstEntry.processingStart - firstEntry.startTime);
      }).observe({ entryTypes: ['first-input'] });
    });
  }

  // Utility functions
  calculateAverage(values) {
    return values.length > 0 ? values.reduce((a, b) => a + b, 0) / values.length : 0;
  }

  // Send metrics to analytics
  sendMetrics(type, data) {
    // Send to Vercel Analytics
    if (window.va) {
      window.va('track', type, data);
    }

    // Send to custom analytics endpoint
    fetch('/api/analytics', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type, data, timestamp: new Date().toISOString() })
    }).catch(console.error);
  }

  // Get current performance snapshot
  getSnapshot() {
    return {
      ...this.metrics,
      timestamp: new Date().toISOString(),
      userAgent: navigator.userAgent,
      viewport: {
        width: window.innerWidth,
        height: window.innerHeight
      }
    };
  }
}

// Initialize performance monitoring
export const performanceMonitor = new PerformanceMonitor();

// Export for use in components
export default PerformanceMonitor;
"""

