analytics_config = """// Vercel Analytics Integration
// Advanced monitoring and user behavior tracking

import { Analytics } from '@vercel/analytics/react';
import { SpeedInsights } from '@vercel/speed-insights/next';

// Analytics Configuration
export const AnalyticsConfig = {
  // Vercel Analytics
  vercel: {
    enabled: process.env.NODE_ENV === 'production',
    debug: process.env.NODE_ENV === 'development',
    beforeSend: (event) => {
      // Filter out sensitive data
      if (event.url?.includes('/api/revenue/') && event.url?.includes('key=')) {
        return null; // Don't track sensitive revenue API calls
      }
      return event;
    }
  },

  // Custom tracking events
  events: {
    // Revenue tracking
    revenue: {
      subscription_started: 'subscription_started',
      payment_completed: 'payment_completed',
      usage_limit_reached: 'usage_limit_reached',
      upgrade_clicked: 'upgrade_clicked'
    },

    // AI usage tracking
    ai: {
      api_call_made: 'ai_api_call',
      model_selected: 'ai_model_selected',
      processing_completed: 'ai_processing_completed',
      error_occurred: 'ai_error'
    },

    // User engagement
    engagement: {
      feature_used: 'feature_used',
      tutorial_completed: 'tutorial_completed',
      feedback_submitted: 'feedback_submitted'
    }
  }
};

// Custom Analytics Hook
export function useAnalytics() {
  const trackEvent = (eventName, properties = {}) => {
    // Track to Vercel Analytics
    if (typeof window !== 'undefined' && window.va) {
      window.va('track', eventName, properties);
    }

    // Track to custom analytics endpoint
    fetch('/api/analytics/track', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        event: eventName,
        properties: {
          ...properties,
          timestamp: new Date().toISOString(),
          url: window.location.href,
          userAgent: navigator.userAgent,
          viewport: {
            width: window.innerWidth,
            height: window.innerHeight
          }
        }
      })
    }).catch(console.error);
  };

  const trackRevenue = (action, amount, currency = 'USD') => {
    trackEvent(AnalyticsConfig.events.revenue[action] || action, {
      amount,
      currency,
      category: 'revenue'
    });
  };

  const trackAIUsage = (model, inputTokens, outputTokens, processingTime) => {
    trackEvent(AnalyticsConfig.events.ai.api_call_made, {
      model,
      inputTokens,
      outputTokens,
      processingTime,
      category: 'ai_usage'
    });
  };

  return {
    trackEvent,
    trackRevenue,
    trackAIUsage
  };
}

// Analytics Provider Component
export function AnalyticsProvider({ children }) {
  return (
    <>
      {children}
      <Analytics />
      <SpeedInsights />
    </>
  );
}

export default AnalyticsConfig;
"""

