        health: health,
        revenue: revenue,
        performance: performance
      }
    };

    res.status(200).json(dashboard);

  } catch (error) {
    console.error('Monitoring dashboard error:', error);
    res.status(500).json({ 
      error: 'Failed to collect metrics',
      timestamp: new Date().toISOString()
    });
  }
}

async function collectSystemMetrics() {
  return {
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    cpu: process.cpuUsage(),
    nodeVersion: process.version,
    platform: process.platform,
    arch: process.arch
  };
}

async function performHealthChecks() {
  const checks = [];

  // Check HuggingFace API
  try {
    const hfResponse = await fetch(
      'https://api-inference.huggingface.co/models/gpt2',
      {
        headers: { Authorization: `Bearer ${process.env.HF_TOKEN}` },
        timeout: 5000
      }
    );
    checks.push({
      service: 'huggingface_api',
      status: hfResponse.ok ? 'healthy' : 'degraded',
      responseTime: hfResponse.headers.get('x-response-time') || 'unknown',
      statusCode: hfResponse.status
    });
  } catch (error) {
    checks.push({
      service: 'huggingface_api',
      status: 'unhealthy',
      error: error.message
    });
  }

  // Check database connection (if using Supabase)
  if (process.env.SUPABASE_URL) {
    try {
      const dbResponse = await fetch(`${process.env.SUPABASE_URL}/rest/v1/`, {
        headers: { 
          apikey: process.env.SUPABASE_ANON_KEY,
          Authorization: `Bearer ${process.env.SUPABASE_ANON_KEY}`
        },
        timeout: 3000
      });
      checks.push({
        service: 'database',
        status: dbResponse.ok ? 'healthy' : 'degraded',
        statusCode: dbResponse.status
      });
    } catch (error) {
      checks.push({
        service: 'database',
        status: 'unhealthy',
        error: error.message
      });
    }
  }

  // Overall health status
  const overall = checks.every(check => check.status === 'healthy') 
    ? 'healthy' 
    : checks.some(check => check.status === 'unhealthy') 
      ? 'unhealthy' 
      : 'degraded';

  return {
    overall,
    checks,
    timestamp: new Date().toISOString()
  };
}

async function getRevenueMetrics() {
