    };

    this.activeAlerts = new Map();
    this.alertHistory = [];
  }

  async checkSystemHealth() {
    try {
      const metrics = await this.collectMetrics();

      // Check various health indicators
      await Promise.all([
        this.checkErrorRate(metrics.errorRate),
        this.checkResponseTime(metrics.responseTime),
        this.checkUptime(metrics.uptime),
        this.checkRevenueHealth(metrics.revenue)
      ]);

    } catch (error) {
      await this.sendAlert('system_check_failed', {
        message: 'Health check system failed',
        error: error.message,
        severity: 'critical'
      });
    }
  }

  async checkErrorRate(errorRate) {
    if (errorRate > this.config.thresholds.errorRate) {
      await this.sendAlert('high_error_rate', {
        message: `Error rate is ${(errorRate * 100).toFixed(2)}%`,
        value: errorRate,
        threshold: this.config.thresholds.errorRate,
        severity: 'warning'
      });
    }
  }

  async checkResponseTime(responseTime) {
    if (responseTime > this.config.thresholds.responseTime) {
      await this.sendAlert('high_response_time', {
        message: `API response time is ${responseTime}ms`,
        value: responseTime,
        threshold: this.config.thresholds.responseTime,
        severity: 'warning'
      });
    }
  }

  async checkUptime(uptime) {
    if (uptime < this.config.thresholds.uptimePercent) {
      await this.sendAlert('low_uptime', {
        message: `System uptime is ${uptime}%`,
        value: uptime,
        threshold: this.config.thresholds.uptimePercent,
        severity: 'critical'
      });
    }
  }

  async checkRevenueHealth(revenueMetrics) {
    const { dailyGrowth, monthlyGrowth } = revenueMetrics;

    if (dailyGrowth < -this.config.thresholds.revenueDropPercent) {
      await this.sendAlert('revenue_drop', {
        message: `Daily revenue dropped by ${Math.abs(dailyGrowth)}%`,
