    if (this.isInCooldown(alertType)) {
      return;
    }

    const alert = {
      id: alertKey,
      type: alertType,
      ...details,
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'unknown'
    };

    // Store alert
    this.activeAlerts.set(alertKey, alert);
    this.alertHistory.push(alert);

