    return cooldownEnd && Date.now() < cooldownEnd;
  }

  setCooldown(alertType) {
    const cooldownKey = `cooldown_${alertType}`;
    const cooldownEnd = Date.now() + (this.config.cooldownMinutes * 60 * 1000);
    this.activeAlerts.set(cooldownKey, cooldownEnd);
